"""Original SVG in two explicitly separate coordinate panels."""
from pathlib import Path
s='''<svg xmlns="http://www.w3.org/2000/svg" width="900" height="360" viewBox="0 0 900 360" role="img" aria-labelledby="title desc"><title id="title">III.6 external and internal tangency</title><desc id="desc">Two independently scaled teaching panels. External tangency: radii 2 and 3, centers 5 apart. Internal tangency: radii 5 and 2, centers 3 apart. Centers remain distinct.</desc><rect width="900" height="360" fill="white"/><g font-family="sans-serif" fill="#172033"><text x="35" y="30" font-size="20">External: d = r1 + r2</text><text x="485" y="30" font-size="20">Internal: d = r1 - r2</text><text x="35" y="330" font-size="15">Independent scales; original teaching diagrams, not source figures.</text></g><g fill="none" stroke-width="2"><circle cx="125" cy="170" r="70" stroke="#215bb5"/><circle cx="300" cy="170" r="105" stroke="#b73f38"/><line x1="125" y1="170" x2="300" y2="170" stroke="#6a7080"/><circle cx="625" cy="170" r="125" stroke="#215bb5"/><circle cx="700" cy="170" r="50" stroke="#b73f38"/><line x1="625" y1="170" x2="750" y2="170" stroke="#6a7080"/></g><g fill="#172033"><circle cx="125" cy="170" r="4"/><circle cx="300" cy="170" r="4"/><circle cx="195" cy="170" r="5"/><circle cx="625" cy="170" r="4"/><circle cx="700" cy="170" r="4"/><circle cx="750" cy="170" r="5"/></g><g font-family="sans-serif" font-size="16" fill="#172033"><text x="110" y="198">O1</text><text x="288" y="198">O2</text><text x="187" y="151">T</text><text x="610" y="198">O1</text><text x="686" y="198">O2</text><text x="755" y="155">T</text><text x="145" y="160">2</text><text x="245" y="160">3</text><text x="665" y="150">3</text><text x="718" y="160">2</text></g></svg>'''
Path('figures').mkdir(exist_ok=True);Path('figures/tangency.svg').write_text(s+'\n');print('original two-panel SVG written')
